// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;

    function setUp() public { c = new Owned(); }

    function testFuzz_property(address currentOwner, address newOwner) public {
        vm.assume(currentOwner != address(0));
        vm.assume(newOwner != address(0));

        vm.assume(currentOwner != newOwner);

        CFactory factory = new CFactory();
        Owned cc = factory.deployWithOwner(currentOwner);

        assertTrue(cc.owner() == currentOwner);

        vm.prank(currentOwner);
        cc.transferOwnership(newOwner);

        assertTrue(cc.owner() == newOwner);
    }
}

contract CFactory {
    function deployWithOwner(address desiredOwner) external returns (Owned) {
        CImpl impl = new CImpl(desiredOwner);
        return Owned(address(impl));
    }
}

contract CImpl is Owned {
    constructor(address desiredOwner) {
        owner = desiredOwner;
    }
}
